/**
 * VirtueMart auth helpers.
 *
 * VirtueMart documents no REST/JSON web-service API and no API token
 * (https://docs.virtuemart.net/vm-api: "The VirtueMart API documentation is
 * generated by the tool Doxygen.", a PHP code reference). There is no OAuth
 * authorize URL, so `getAuthUrl` and `exchangeCode` throw, and
 * `refreshCredentials` returns the stored credentials unchanged.
 *
 * Connections still store `accessToken` and `extra.baseUrl` (unchanged), but
 * every read method refuses with 501 NOT_SUPPORTED; see index.ts.
 */

import type { Credentials } from '@opensteward/shared'

export function getAuthUrl(_state: string): string {
  throw new Error(
    'VirtueMart has no OAuth authorize URL: it documents no REST API or API token ' +
      '(https://docs.virtuemart.net/vm-api). Connections are registered via POST /v1/connections.',
  )
}

export async function exchangeCode(_code: string, _redirectUri: string): Promise<Credentials> {
  throw new Error(
    'VirtueMart has no OAuth flow, so exchangeCode is not applicable. ' +
      'Connections are registered via POST /v1/connections.',
  )
}

export async function refreshCredentials(credentials: Credentials): Promise<Credentials> {
  // No documented token lifecycle: return the stored credentials unchanged.
  return credentials
}
